         doc->Commit();
         SelectOnly(c);
         sClip.clear();
         sPending.what = Pending::CopyMerged;
         RunPending(doc);
         expect("Copy Merged fills the clip and leaves the layers alone", !sClip.empty() && doc->Layers().size() == before);
         sClip.clear();
